import java.util.*;
import java.io.*;

public class Main {
    static final long M1 = 998244353L;
    static final long M2 = 1000000007L;
    static long result = 0;
    static long totalCount;
    static long counter;
    static List<Long>[] digitValues = new ArrayList[7];
    static long[] prefixSum = new long[7];
    static long[] powArr = {1, 10, 100, 1000, 10000, 100000, 1000000};
    static long countPairs;
    static long total;

    static {
        for (int i = 0; i < 7; i++) {
            digitValues[i] = new ArrayList<>();
        }
    }

    static void buildValues(int depth, long num) {
        if (depth == 7) return;
        long val = (totalCount - num + M1) % M1;
        digitValues[depth].add(val);
        prefixSum[depth] += val;
        totalCount++;
        for (int d = 0; d <= 9; d++) {
            buildValues(depth + 1, num * 10 + d);
        }
    }

    static boolean inRange(long x) {
        return x * 1000000 + 999999 <= totalCount && x * 10000000 > totalCount;
    }

    static void search(long level, long val) {
        if (val > totalCount) return;
        if (inRange(val)) {
            for (int i = 0; i <= 6; i++) {
                long off = ((countPairs + 1 - (val * powArr[i]) % M1) + M1) % M1;
                List<Long> list = digitValues[i];
                int pos = lowerBound(list, M1 - off);
                long size = list.size();
                result = (result + (prefixSum[i] + off * size - M1 * (size - pos))) % M2;
            }
            countPairs += total;
        } else {
            countPairs++;
            result = (result + ((countPairs - val) % M1 + M1) % M1) % M2;
            for (int d = (level == 0 ? 1 : 0); d <= 9; d++) {
                search(level + 1, val * 10 + d);
            }
        }
    }

    static int lowerBound(List<Long> list, long key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        totalCount = Long.parseLong(br.readLine().trim());
        buildValues(0, 0);
        for (int i = 0; i <= 6; i++) {
            Collections.sort(digitValues[i]);
        }
        countPairs = -1;
        search(0, 0);
        System.out.println(result);
    }
}
